use std::fs
use std::collections::HashMap

fn amt(s: string) -> int {
    s.parse::<int>().unwrap_or(0)
}

fn bal_of(m: HashMap<string, int>, k: string) -> int {
    match m.get(k) {
        Some(v) => v,
        None => 0,
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 { continue }
        let cmd = parts[0].clone()
        if cmd == "open" {
            let name = parts[1].clone()
            let a = amt(parts[2].clone())
            if a < 0 { println("error: invalid amount") }
            else if acc.contains_key(name) { println("error: duplicate account") }
            else {
                acc.insert(name, a)
                println("ok")
            }
        } else if cmd == "deposit" || cmd == "withdraw" {
            let name = parts[1].clone()
            let a = amt(parts[2].clone())
            if a <= 0 { println("error: invalid amount") }
            else if !acc.contains_key(name) { println("error: unknown account ${name}") }
            else {
                let bal = bal_of(acc, name)
                if cmd == "deposit" {
                    acc.insert(name, bal + a)
                    println("ok")
                } else if bal < a {
                    println("error: insufficient funds")
                } else {
                    acc.insert(name, bal - a)
                    println("ok")
                }
            }
        } else if cmd == "transfer" {
            let f = parts[1].clone()
            let t = parts[2].clone()
            let a = amt(parts[3].clone())
            if a <= 0 { println("error: invalid amount") }
            else if !acc.contains_key(f) { println("error: unknown account ${f}") }
            else if !acc.contains_key(t) { println("error: unknown account ${t}") }
            else if f == t { println("error: same account") }
            else {
                let fb = bal_of(acc, f)
                let tb = bal_of(acc, t)
                if fb < a { println("error: insufficient funds") }
                else {
                    acc.insert(f, fb - a)
                    acc.insert(t, tb + a)
                    println("ok")
                }
            }
        } else if cmd == "balance" {
            let name = parts[1].clone()
            if !acc.contains_key(name) { println("error: unknown account ${name}") }
            else { println("${bal_of(acc, name)}") }
        }
    }
    let mut keys: Vec<string> = []
    for k in acc.keys() { keys.push(k.clone()) }
    keys.sort()
    for k in keys {
        println("${k} ${bal_of(acc, k)}")
    }
}

